INSERT INTO `case_objectives` (`objective_id`, `case_id`, `objective_order`, `objective_text`, `expected_query`, `validation_type`, `required_keyword`, `points`) VALUES 
(120025, 60059, 1, 'Registry Sweep: Inspect all suspects and their recorded investigation status.', 'SELECT name, status FROM suspects', 'result', NULL, 33),
(120026, 60059, 2, 'Filter Open Leads: Filter suspects whose status is \"Under Investigation\".', 'SELECT name, status FROM suspects WHERE status = \'Under Investigation\'', 'result', NULL, 33),
(120027, 60059, 3, 'Dossier Extraction: Extract the names and ages of all active persons of interest.', 'SELECT name, age FROM suspects WHERE status = \'Under Investigation\'', 'result', NULL, 34),
(120028, 60060, 1, 'Evidence Vault Survey: View all logged physical items and their severity ratings.', 'SELECT item_name, severity FROM evidence', 'result', NULL, 33),
(120029, 60060, 2, 'Filter Dangerous Clues: Restrict the query to items with severity >= 4.', 'SELECT item_name, severity FROM evidence WHERE severity >= 4', 'result', NULL, 33),
(120030, 60060, 3, 'Lab Priority Tagging: Extract item_name and severity for expedited lab analysis.', 'SELECT item_name, severity FROM evidence WHERE severity >= 4', 'result', NULL, 34),
(120031, 60061, 1, 'District Location Audit: Inspect all registered locations and their active status.', 'SELECT place_name, district, is_active FROM locations', 'result', NULL, 33),
(120032, 60061, 2, 'Filter Active Scenes: Restrict the query to locations where is_active = 1.', 'SELECT place_name, district, is_active FROM locations WHERE is_active = 1', 'result', NULL, 33),
(120033, 60061, 3, 'Patrol Dispatch Dossier: Display place_name and district for all active zones.', 'SELECT place_name, district FROM locations WHERE is_active = 1', 'result', NULL, 34),
(120034, 60062, 1, 'Witness Roster Scan: Query the witnesses table to review all civilian accounts.', 'SELECT * FROM witnesses', 'result', NULL, 33),
(120035, 60062, 2, 'Extract Phone Numbers: Select each witness’s full name and contact number.', 'SELECT full_name, contact_number FROM witnesses', 'result', NULL, 33),
(120036, 60062, 3, 'Complete Contact Sheet: Confirm full witness directory for dispatch outreach.', 'SELECT full_name, contact_number FROM witnesses', 'result', NULL, 34),
(120037, 60063, 1, 'Precinct Duty Roster: View all officers along with their assigned ranks.', 'SELECT name, badge_number, rank_level FROM officers', 'result', NULL, 33),
(120038, 60063, 2, 'Filter Junior Rank: Filter the roster for officers with rank_level = \"Junior Officer\".', 'SELECT name, badge_number, rank_level FROM officers WHERE rank_level = \'Junior Officer\'', 'result', NULL, 33),
(120039, 60063, 3, 'Deploy Patrol Units: Extract the name and badge number of the qualifying junior officer.', 'SELECT name, badge_number FROM officers WHERE rank_level = \'Junior Officer\'', 'result', NULL, 34),
(120040, 60064, 1, 'Relational Link: Join evidence items with their corresponding crime scene place names.', 'SELECT e.item_name, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id', 'result', NULL, 66),
(120041, 60064, 2, 'Group by Scene: Group records by place_name to aggregate item counts.', 'SELECT l.place_name, COUNT(e.evidence_id) FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 'result', NULL, 67),
(120042, 60064, 3, 'Evidence Count Report: Show place_name and count using column alias evidence_count.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 'result', NULL, 67),
(120043, 60065, 1, 'Age Distribution Sweep: Query all suspect names, ages, and statuses.', 'SELECT name, age, status FROM suspects', 'result', NULL, 66),
(120044, 60065, 2, 'Filter Veteran Operators: Restrict to suspects strictly older than 30 years old.', 'SELECT name, age, status FROM suspects WHERE age > 30', 'result', NULL, 67),
(120045, 60065, 3, 'Order by Seniority: Order the results by age descending (ORDER BY age DESC).', 'SELECT name, age, status FROM suspects WHERE age > 30 ORDER BY age DESC', 'result', NULL, 67),
(120046, 60066, 1, 'Map Item Severities: Join evidence to locations and display place_name and severity.', 'SELECT l.place_name, e.severity FROM evidence e JOIN locations l ON e.location_id = l.location_id', 'result', NULL, 66),
(120047, 60066, 2, 'Compute Scene Averages: Group by place_name and compute AVG(severity) as avg_severity.', 'SELECT l.place_name, AVG(e.severity) AS avg_severity FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 'result', NULL, 67),
(120048, 60066, 3, 'Rank Scene Threats: Order the grouped results by avg_severity DESC.', 'SELECT l.place_name, AVG(e.severity) AS avg_severity FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY avg_severity DESC', 'result', NULL, 67),
(120049, 60067, 1, 'Identify Distinct Categories: View distinct status tags recorded in the suspects table.', 'SELECT DISTINCT status FROM suspects', 'result', NULL, 66),
(120050, 60067, 2, 'Aggregate by Status: Group suspects by status and calculate total occurrences.', 'SELECT status, COUNT(*) FROM suspects GROUP BY status', 'result', NULL, 67),
(120051, 60067, 3, 'Caseload Summary: Produce the final status summary using column alias count.', 'SELECT status, COUNT(*) AS count FROM suspects GROUP BY status', 'result', NULL, 67),
(120052, 60068, 1, 'Assemble Forensic Catalog: LEFT JOIN evidence with locations to view item, severity, and place.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e LEFT JOIN locations l ON e.location_id = l.location_id', 'result', NULL, 66),
(120053, 60068, 2, 'Order by Threat Level: Sort all evidence items by severity descending.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e LEFT JOIN locations l ON e.location_id = l.location_id ORDER BY e.severity DESC', 'result', NULL, 67),
(120054, 60068, 3, 'Master Ballistics Queue: Confirm the complete evidence queue sorted by severity DESC.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e LEFT JOIN locations l ON e.location_id = l.location_id ORDER BY e.severity DESC', 'result', NULL, 67),
(120055, 60069, 1, 'Outer Join Assessment: LEFT JOIN locations with evidence to inspect evidence links.', 'SELECT l.place_name, e.evidence_id FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id', 'result', NULL, 100),
(120056, 60069, 2, 'Isolate Unlinked Scenes: Filter for rows where evidence_id IS NULL.', 'SELECT l.place_name, e.evidence_id FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id WHERE e.evidence_id IS NULL', 'result', NULL, 100),
(120057, 60069, 3, 'Identify Cold Scene: Return clean place name of the location with no evidence found.', 'SELECT l.place_name FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id WHERE e.evidence_id IS NULL', 'result', NULL, 100),
(120058, 60070, 1, 'Aggregate Scene Evidence: Group evidence by location and compute evidence counts.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 'result', NULL, 100),
(120059, 60070, 2, 'Apply Group Threshold: Filter using HAVING to isolate locations with COUNT(evidence_id) > 1.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name HAVING COUNT(e.evidence_id) > 1', 'result', NULL, 100),
(120060, 60070, 3, 'Confirm Hotspot Location: Expose the hotspot location name and count of evidence items.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name HAVING COUNT(e.evidence_id) > 1', 'result', NULL, 100),
(120061, 60071, 1, 'Order Scenes by Activity: Group evidence by location and order by count descending.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY evidence_count DESC', 'result', NULL, 100),
(120062, 60071, 2, 'Isolate Top Crime Scene: Restrict the output to the single top location using LIMIT 1.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY evidence_count DESC LIMIT 1', 'result', NULL, 100),
(120063, 60071, 3, 'Confirm Heist Headquarters: Reveal Central Warehouse as the primary heist headquarters.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY evidence_count DESC LIMIT 1', 'result', NULL, 100),
(120064, 60072, 1, 'Query Suspect Roster Block: Select suspect name as label and status as value from suspects.', 'SELECT name AS label, status AS value FROM suspects', 'result', NULL, 100),
(120065, 60072, 2, 'Query Evidence Block: Select item_name as label and CAST(severity AS CHAR) as value from evidence.', 'SELECT item_name AS label, CAST(severity AS CHAR) AS value FROM evidence', 'result', NULL, 100),
(120066, 60072, 3, 'Execute Master UNION: Merge both result sets into a single unified prosecution report.', 'SELECT name AS label, status AS value FROM suspects UNION SELECT item_name AS label, CAST(severity AS CHAR) AS value FROM evidence', 'result', NULL, 100),
(120067, 60073, 1, 'Cross-Match High Severity: Join evidence and locations filtering for severity >= 4.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id WHERE e.severity >= 4', 'result', NULL, 100),
(120068, 60073, 2, 'Filter Active Locations: Require location is_active = 1 to isolate active scene evidence.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id WHERE e.severity >= 4 AND l.is_active = 1', 'result', NULL, 100),
(120069, 60073, 3, 'Warrant Conclusive Clues: Display item_name, severity, and place_name confirming the warrant grounds.', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id WHERE e.severity >= 4 AND l.is_active = 1', 'result', NULL, 100),
