(120102, 60114, 3, 'Redeployment Roster: Return the clean place name of the location with zero evidence logged.', 'SELECT l.place_name FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id WHERE e.evidence_id IS NULL', 'result', NULL, 100),
(120103, 60115, 1, 'Aggregate Scene Counts: Group evidence by location and calculate evidence counts per scene.', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 'result', NULL, 100),
