(60057, 'Transfer Warehouse Evidence to Police HQ', 'Due to safety risks at Central Warehouse (location_id = 2), transfer all evidence stored there to Police HQ (location_id = 4).', '📋 OBJECTIVES:\n1. Use UPDATE evidence. (30 XP)\n2. Set location_id = 4. (35 XP)\n3. Target WHERE location_id = 2. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'UPDATE evidence SET location_id = 4 WHERE location_id = 2', 300, 1, 0, NULL, 'Practice', 'DML', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (location_id INT AUTO_INCREMENT PRIMARY KEY, place_name VARCHAR(100) NOT NULL, district VARCHAR(100), is_active TINYINT(1) DEFAULT 1);\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50));\nCREATE TABLE suspects (suspect_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, age INT, status VARCHAR(50) DEFAULT \'Under Investigation\');\nCREATE TABLE witnesses (witness_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, contact_number VARCHAR(20));\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, severity INT DEFAULT 1, location_id INT, collected_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (location_id) REFERENCES locations(location_id) ON DELETE SET NULL);\nINSERT INTO locations VALUES (1,\'City Hall\',\'Downtown\',1),(2,\'Central Warehouse\',\'Industrial Zone\',1),(3,\'Riverside Park\',\'Northside\',1),(4,\'Police HQ\',\'Central\',1),(5,\'Abandoned Factory\',\'Southside\',0);\nINSERT INTO officers VALUES (1,\'B-001\',\'Officer Santos\',\'Detective\'),(2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),(3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES (1,\'Marcus Webb\',32,\'Under Investigation\'),(2,\'Lena Torres\',28,\'Under Investigation\'),(3,\'Victor Hale\',45,\'Cleared\'),(4,\'Diana Cruz\',39,\'Arrested\'),(5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES (1,\'Carmen Sia\',\'09171234567\'),(2,\'Roberto Ngo\',\'09281234567\'),(3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),(2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),(3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),(4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),(5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\')', 'SELECT evidence_id, item_name, severity, location_id FROM evidence ORDER BY evidence_id', 2),
(60058, 'Purge Inactive Crime Scene Locations', 'Decommission all inactive investigation scenes. Delete all locations from `locations` where `is_active = 0` (linked evidence will be preserved with location_id set to NULL).', '📋 OBJECTIVES:\n1. Use DELETE FROM locations. (30 XP)\n2. Filter by WHERE is_active = 0. (35 XP)\n3. Ensure active locations remain untouched. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'DELETE FROM locations WHERE is_active = 0', 300, 1, 0, NULL, 'Practice', 'DML', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (location_id INT AUTO_INCREMENT PRIMARY KEY, place_name VARCHAR(100) NOT NULL, district VARCHAR(100), is_active TINYINT(1) DEFAULT 1);\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50));\nCREATE TABLE suspects (suspect_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, age INT, status VARCHAR(50) DEFAULT \'Under Investigation\');\nCREATE TABLE witnesses (witness_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, contact_number VARCHAR(20));\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, severity INT DEFAULT 1, location_id INT, collected_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (location_id) REFERENCES locations(location_id) ON DELETE SET NULL);\nINSERT INTO locations VALUES (1,\'City Hall\',\'Downtown\',1),(2,\'Central Warehouse\',\'Industrial Zone\',1),(3,\'Riverside Park\',\'Northside\',1),(4,\'Police HQ\',\'Central\',1),(5,\'Abandoned Factory\',\'Southside\',0);\nINSERT INTO officers VALUES (1,\'B-001\',\'Officer Santos\',\'Detective\'),(2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),(3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES (1,\'Marcus Webb\',32,\'Under Investigation\'),(2,\'Lena Torres\',28,\'Under Investigation\'),(3,\'Victor Hale\',45,\'Cleared\'),(4,\'Diana Cruz\',39,\'Arrested\'),(5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES (1,\'Carmen Sia\',\'09171234567\'),(2,\'Roberto Ngo\',\'09281234567\'),(3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),(2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),(3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),(4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),(5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\')', 'SELECT location_id, place_name, district, is_active FROM locations ORDER BY location_id', 2),
(60059, 'The Riverside Suspects Sweep', '📁 CASE BRIEFING: A series of coordinated break-ins struck Riverside District. Detective Santos assigned you to scan the municipal registry and isolate all persons of interest marked as \"Under Investigation\".', '1. Registry Sweep: Inspect all suspects and their recorded investigation status.\n2. Filter Open Leads: Filter suspects whose status is \"Under Investigation\".\n3. Dossier Extraction: Extract the names and ages of all active persons of interest.', 1, 1, 'SELECT name, age FROM suspects WHERE status = \'Under Investigation\'', 100, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Facto