(60062, 'Eyewitness Phone Directory', '📁 CASE BRIEFING: Civilians reported strange noises and suspicious vehicles near the Riverside scene. Assemble a clean telephone directory of all registered witnesses for detective follow-up.', '1. Witness Roster Scan: Query the witnesses table to review all civilian accounts.\n2. Extract Phone Numbers: Select each witness’s full name and contact number.\n3. Complete Contact Sheet: Confirm full witness directory for dispatch outreach.', 1, 1, 'SELECT full_name, contact_number FROM witnesses', 100, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT full_name, contact_number FROM witnesses', 3),
(60063, 'Patrol Junior Officers Assignment', '📁 CASE BRIEFING: Perimeter security at Riverside Park needs reinforcements. Query the officer registry for all personnel holding the rank of \"Junior Officer\" to deploy them on patrol.', '1. Precinct Duty Roster: View all officers along with their assigned ranks.\n2. Filter Junior Rank: Filter the roster for officers with rank_level = \"Junior Officer\".\n3. Deploy Patrol Units: Extract the name and badge number of the qualifying junior officer.', 1, 1, 'SELECT name, badge_number FROM officers WHERE rank_level = \'Junior Officer\'', 100, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT name, badge_number FROM officers WHERE rank_level = \'Junior Officer\'', 3),
(60064, 'Scene Evidence Density', '📁 CASE BRIEFING: Detectives need an overview of evidence distribution. Join evidence to locations and compute the total count of items discovered at each distinct crime scene.', '1. Relational Link: Join evidence items with their corresponding crime scene place names.\n2. Group by Scene: Group records by place_name to aggregate item counts.\n3. Evidence Count Report: Show place_name and count using column alias evidence_count.', 1, 2, 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 200, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name', 3),
(60065, 'Veteran Suspects Profile', '📁 CASE BRIEFING: The syndicate appears to be led by experienced operators. Filter the suspect registry to isolate individuals older than 30, ordering them from oldest to youngest.', '1. Age Distribution Sweep: Query all suspect names, ages, and statuses.\n2. Filter Veteran Operators: Restrict to suspects strictly older than 30 years old.\n3. Order by Seniority: Order the results by age descending (ORDER BY age DESC).', 1, 2, 'SELECT name, age, status FROM suspects WHERE age > 30 ORDER BY age DESC', 200, 1, 0, 4, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT name, age, status FROM suspects WHERE age > 30 ORDER BY age DESC', 3),
(60066, 'Average Scene Threat Rating', '📁 CASE BRIEFING: Analyze crime scene risk factors across the city. Join evidence and locations to calculate the average severity rating per scene, ordered from highest average threat descending.', '1. Map Item Severities: Join evidence to locations and display place_name and severity.\n2. Compute Scene Averages: Group by place_name and compute AVG(severity) as avg_severity.\n3. Rank Scene Threats: Order the grouped results by avg_severity DESC.', 1, 2, 'SELECT l.place_name, AVG(e.severity) AS avg_severity FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY avg_severity DESC', 200, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT l.place_name, AVG(e.severity) AS avg_severity FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY avg_severity DESC', 3),
(60067, 'Syndicate Status Audit', '📁 CASE BRIEFING: Provide a statistical overview of the suspect database for the district attorney. Group all suspects by investigation status and count how many fall under each category.', '1. Identify Distinct Categories: View distinct status tags recorded in the suspects table.\n2. Aggregate by Status: Group suspects by status and calculate total occurrences.\n3. Caseload Summary: Produce the final status summary using column alias count.', 1, 2, 'SELECT status, COUNT(*) AS count FROM suspects GROUP BY status', 200, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT status, COUNT(*) AS count FROM suspects GROUP BY status', 3),
(60068, 'Critical Evidence Registry', '📁 CASE BRIEFING: Prepare the master evidence ledger for ballistic specialists. Include item names, severity, and location names, sorted from highest severity down to lowest.', '1. Assemble Forensic Catalog: LEFT JOIN evidence with locations to view item, severity, and place.\n2. Order by Threat Level: Sort all evidence items by severity descending.\n3. Master Ballistics Queue: Confirm the complete evidence queue sorted by severity DESC.', 1, 2, 'SELECT e.item_name, e.severity, l.place_name FROM evidence e LEFT JOIN locations l ON e.location_id = l.location_id ORDER BY e.severity DESC', 200, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e LEFT JOIN locations l ON e.location_id = l.location_id ORDER BY e.severity DESC', 3),
(60069, 'Cold Scene Search', '📁 CASE BRIEFING: Detectives suspect some registered locations were false leads. Perform an outer join to identify municipal locations where no evidence has been tagged yet.', '1. Outer Join Assessment: LEFT JOIN locations with evidence to inspect evidence links.\n2. Isolate Unlinked Scenes: Filter for rows where evidence_id IS NULL.\n3. Identify Cold Scene: Return clean place name of the location with no evidence found.', 1, 3, 'SELECT l.place_name FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id WHERE e.evidence_id IS NULL', 300, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT l.place_name FROM locations l LEFT JOIN evidence e ON l.location_id = e.location_id WHERE e.evidence_id IS NULL', 3),
(60070, 'Multi-Evidence Hotspots', '📁 CASE BRIEFING: Locate crime scenes where multiple distinct physical clues were recovered. Group evidence by location and apply a HAVING condition for counts greater than 1.', '1. Aggregate Scene Evidence: Group evidence by location and compute evidence counts.\n2. Apply Group Threshold: Filter using HAVING to isolate locations with COUNT(evidence_id) > 1.\n3. Confirm Hotspot Location: Expose the hotspot location name and count of evidence items.', 1, 3, 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name HAVING COUNT(e.evidence_id) > 1', 300, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name HAVING COUNT(e.evidence_id) > 1', 3),
(60071, 'The Primary Warehouse Focal Point', '📁 CASE BRIEFING: Identify the single most significant location of the entire Riverside investigation by isolating the scene with the highest total evidence items (LIMIT 1).', '1. Order Scenes by Activity: Group evidence by location and order by count descending.\n2. Isolate Top Crime Scene: Restrict the output to the single top location using LIMIT 1.\n3. Confirm Heist Headquarters: Reveal Central Warehouse as the primary heist headquarters.', 1, 3, 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY evidence_count DESC LIMIT 1', 300, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT l.place_name, COUNT(e.evidence_id) AS evidence_count FROM evidence e JOIN locations l ON e.location_id = l.location_id GROUP BY l.place_name ORDER BY evidence_count DESC LIMIT 1', 3),
(60072, 'Consolidated Investigation Master Record', '📁 CASE BRIEFING: Prepare the unified prosecution brief. Use a UNION query to combine all suspect names and statuses with all tagged evidence items and their severity ratings.', '1. Query Suspect Roster Block: Select suspect name as label and status as value from suspects.\n2. Query Evidence Block: Select item_name as label and CAST(severity AS CHAR) as value from evidence.\n3. Execute Master UNION: Merge both result sets into a single unified prosecution report.', 1, 3, 'SELECT name AS label, status AS value FROM suspects UNION SELECT item_name AS label, CAST(severity AS CHAR) AS value FROM evidence', 300, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT name AS label, status AS value FROM suspects UNION SELECT item_name AS label, CAST(severity AS CHAR) AS value FROM evidence', 3),
(60073, 'Active Zone Lethal Evidence', '📁 CASE BRIEFING: Assemble the final evidence packet for the arrest warrant. Filter for all high-severity evidence items (severity >= 4) discovered specifically in active investigation zones (is_active = 1).', '1. Cross-Match High Severity: Join evidence and locations filtering for severity >= 4.\n2. Filter Active Locations: Require location is_active = 1 to isolate active scene evidence.\n3. Warrant Conclusive Clues: Display item_name, severity, and place_name confirming the warrant grounds.', 1, 3, 'SELECT e.item_name, e.severity, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id WHERE e.severity >= 4 AND l.is_active = 1', 300, 1, 0, 1, 'Practice', 'DQL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );\nINSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');', 'SELECT e.item_name, e.severity, l.place_name FROM evidence e JOIN locations l ON e.location_id = l.location_id WHERE e.severity >= 4 AND l.is_active = 1', 3),
(60074, 'Operation Blackout — Deploy Suspect Intake Registry', 'A citywide blackout struck City Hall. Detectives must deploy the emergency `suspects` registry table:\n- suspect_id (INT, PRIMARY KEY, AUTO_INCREMENT)\n- name (VARCHAR 100, NOT NULL)\n- age (INT)\n- status (VARCHAR 50, DEFAULT \"Under Investigation\")', '📋 OBJECTIVES:\n1. Deploy suspects table with suspect_id as PRIMARY KEY AUTO_INCREMENT. (30 XP)\n2. Ensure name is VARCHAR(100) NOT NULL. (35 XP)\n3. Set status default to \'Under Investigation\'. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'CREATE TABLE suspects (\n  suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n  name VARCHAR(100) NOT NULL,\n  age INT,\n  status VARCHAR(50) DEFAULT \'Under Investigation\'\n)', 100, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS suspects', 'SHOW COLUMNS FROM suspects', 1),
(60075, 'Operation Blackout — Deploy Civilian Witness Registry', 'Civilians trapped in the plaza witnessed masked operatives. Construct the emergency `witnesses` table:\n- witness_id (INT, PRIMARY KEY, AUTO_INCREMENT)\n- full_name (VARCHAR 100, NOT NULL)\n- contact_number (VARCHAR 20)', '📋 OBJECTIVES:\n1. Deploy witnesses table with witness_id as PRIMARY KEY. (30 XP)\n2. Set full_name as NOT NULL. (35 XP)\n3. Include contact_number column. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'CREATE TABLE witnesses (\n  witness_id INT AUTO_INCREMENT PRIMARY KEY,\n  full_name VARCHAR(100) NOT NULL,\n  contact_number VARCHAR(20)\n)', 100, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS witnesses', 'SHOW COLUMNS FROM witnesses', 1),
(60076, 'Operation Blackout — Deploy Chain of Custody Table', 'Tactical officers are securing dropped weapons and electronic devices. Construct the emergency `evidence` table:\n- evidence_id (INT, PRIMARY KEY, AUTO_INCREMENT)\n- item_name (VARCHAR 100, NOT NULL)\n- severity (INT, DEFAULT 1)\n- location_id (INT)', '📋 OBJECTIVES:\n1. Deploy evidence table with evidence_id PK AI. (30 XP)\n2. Ensure item_name is NOT NULL. (35 XP)\n3. Set severity with DEFAULT 1. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'CREATE TABLE evidence (\n  evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n  item_name VARCHAR(100) NOT NULL,\n  severity INT DEFAULT 1,\n  location_id INT\n)', 100, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS evidence', 'SHOW COLUMNS FROM evidence', 1),
(60077, 'Operation Blackout — Deploy Municipal Zones Table', 'Dispatch requires a perimeter monitoring table. Construct the emergency `locations` table:\n- location_id (INT, PRIMARY KEY, AUTO_INCREMENT)\n- place_name (VARCHAR 100, NOT NULL)\n- district (VARCHAR 100)\n- is_active (TINYINT(1), DEFAULT 1)', '📋 OBJECTIVES:\n1. Deploy locations table with location_id PK AI. (30 XP)\n2. Set place_name as VARCHAR(100) NOT NULL. (35 XP)\n3. Set is_active default to 1. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'CREATE TABLE locations (\n  location_id INT AUTO_INCREMENT PRIMARY KEY,\n  place_name VARCHAR(100) NOT NULL,\n  district VARCHAR(100),\n  is_active TINYINT(1) DEFAULT 1\n)', 100, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS locations', 'SHOW COLUMNS FROM locations', 1),
(60078, 'Operation Blackout — Deploy Tactical Officers Table', 'Emergency response officers are arriving from multiple precincts. Build the `officers` duty table:\n- officer_id (INT, PRIMARY KEY, AUTO_INCREMENT)\n- badge_number (VARCHAR 20, UNIQUE, NOT NULL)\n- name (VARCHAR 100, NOT NULL)\n- rank_level (VARCHAR 50)', '📋 OBJECTIVES:\n1. Deploy officers table with officer_id PK AI. (30 XP)\n2. Enforce UNIQUE constraint on badge_number. (35 XP)\n3. Ensure name is NOT NULL. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'CREATE TABLE officers (\n  officer_id INT AUTO_INCREMENT PRIMARY KEY,\n  badge_number VARCHAR(20) UNIQUE NOT NULL,\n  name VARCHAR(100) NOT NULL,\n  rank_level VARCHAR(50)\n)', 100, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS officers', 'SHOW COLUMNS FROM officers', 1),
(60079, 'Operation Blackout — Enforce Unique Officer Badges', 'Impersonation risk is critical during the blackout. Alter `officers` table to ensure badge numbers are strictly UNIQUE.', '📋 OBJECTIVES:\n1. Use ALTER TABLE officers. (30 XP)\n2. Apply UNIQUE constraint. (35 XP)\n3. Target badge_number column. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 2, 'ALTER TABLE officers ADD UNIQUE (badge_number)', 200, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS officers;\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50))', 'SHOW COLUMNS FROM officers', 1),
(60080, 'Operation Blackout — Add Forensic Tagging Column', 'Bomb squad technicians need specialized tagging on recovered ordnance. Alter `evidence` to add column `notes` (TEXT).', '📋 OBJECTIVES:\n1. Use ALTER TABLE evidence. (30 XP)\n2. Use ADD COLUMN. (35 XP)\n3. Add notes of type TEXT. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 2, 'ALTER TABLE evidence ADD COLUMN notes TEXT', 200, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS evidence;\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, severity INT DEFAULT 1, location_id INT)', 'SHOW COLUMNS FROM evidence', 1),
(60081, 'Operation Blackout — Enforce Default Investigation Status', 'Intake during emergency blackout operations leads to missing entries. Alter `suspects` so `status` defaults to \"Under Investigation\".', '📋 OBJECTIVES:\n1. Use ALTER TABLE suspects. (30 XP)\n2. Modify default on status column. (35 XP)\n3. Set default value to \'Under Investigation\'. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 2, 'ALTER TABLE suspects ALTER COLUMN status SET DEFAULT \'Under Investigation\'', 200, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS suspects;\nCREATE TABLE suspects (suspect_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, age INT, status VARCHAR(50))', 'SHOW COLUMNS FROM suspects', 1),
(60082, 'Operation Blackout — Build Tactical Unit Index', 'Dispatch requires fast lookup of tactical ranks during high radio traffic. Create an index on `officers(rank_level)`.', '📋 OBJECTIVES:\n1. Use CREATE INDEX statement. (30 XP)\n2. Target officers table. (35 XP)\n3. Index the rank_level column. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 2, 'CREATE INDEX idx_officer_rank ON officers (rank_level)', 200, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS officers;\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50))', 'SHOW COLUMNS FROM officers', 1),
(60083, 'Operation Blackout — Link Evidence Foreign Keys', 'Ensure chain-of-custody data integrity. Add a FOREIGN KEY constraint on `evidence.location_id` referencing `locations(location_id)`.', '📋 OBJECTIVES:\n1. Use ALTER TABLE evidence. (30 XP)\n2. Add foreign key on location_id. (35 XP)\n3. Reference locations(location_id). (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 2, 'ALTER TABLE evidence ADD FOREIGN KEY (location_id) REFERENCES locations(location_id)', 200, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (location_id INT AUTO_INCREMENT PRIMARY KEY, place_name VARCHAR(100) NOT NULL, district VARCHAR(100), is_active TINYINT(1) DEFAULT 1);\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, location_id INT, severity INT DEFAULT 1)', 'SHOW COLUMNS FROM evidence', 1),
(60084, 'Operation Blackout — Emergency Assignment Junction Table', 'Deploy rapid tasking table `emergency_assignments`:\n- assignment_id (INT, PK, AI)\n- officer_id (INT, NOT NULL, FK → officers)\n- incident_zone (VARCHAR 100, NOT NULL)\n- deployed_at (DATETIME, DEFAULT CURRENT_TIMESTAMP)', '📋 OBJECTIVES:\n1. Create emergency_assignments table. (30 XP)\n2. Link officer_id with FOREIGN KEY. (35 XP)\n3. Include deployed_at DEFAULT CURRENT_TIMESTAMP. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'CREATE TABLE emergency_assignments (\n  assignment_id INT AUTO_INCREMENT PRIMARY KEY,\n  officer_id INT NOT NULL,\n  incident_zone VARCHAR(100) NOT NULL,\n  deployed_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (officer_id) REFERENCES officers(officer_id)\n)', 300, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS emergency_assignments;\nDROP TABLE IF EXISTS officers;\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50))', 'SHOW COLUMNS FROM emergency_assignments', 1),
(60085, 'Operation Blackout — Enforce Severity Boundary Checks', 'Prevent invalid evidence ratings during high-stress entry. Add a CHECK constraint to `evidence` ensuring `severity` is between 1 and 5.', '📋 OBJECTIVES:\n1. Use ALTER TABLE evidence. (30 XP)\n2. Add CHECK constraint. (35 XP)\n3. Enforce severity between 1 and 5. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'ALTER TABLE evidence ADD CONSTRAINT chk_evidence_severity CHECK (severity >= 1 AND severity <= 5)', 300, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS evidence;\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, severity INT DEFAULT 1, location_id INT)', 'SHOW COLUMNS FROM evidence', 1),
(60086, 'Operation Blackout — Add Witness Contact Unique Constraint', 'Prevent duplicate anonymous tipster entries. Alter `witnesses` table to enforce a UNIQUE constraint on `contact_number`.', '📋 OBJECTIVES:\n1. Use ALTER TABLE witnesses. (30 XP)\n2. Add UNIQUE constraint. (35 XP)\n3. Target contact_number column. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'ALTER TABLE witnesses ADD UNIQUE (contact_number)', 300, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS witnesses;\nCREATE TABLE witnesses (witness_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, contact_number VARCHAR(20))', 'SHOW COLUMNS FROM witnesses', 1),
(60087, 'Operation Blackout — Immutable Audit Log Deployment', 'Construct the tamper-evident `audit_log` table with cascade delete on suspects:\n- log_id (INT, PK, AI)\n- suspect_id (INT, FK → suspects ON DELETE CASCADE)\n- action_summary (VARCHAR 150, NOT NULL)\n- timestamp (DATETIME, DEFAULT CURRENT_TIMESTAMP)', '📋 OBJECTIVES:\n1. Deploy audit_log table with log_id PK AI. (30 XP)\n2. Link suspect_id with ON DELETE CASCADE. (35 XP)\n3. Set timestamp DEFAULT CURRENT_TIMESTAMP. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'CREATE TABLE audit_log (\n  log_id INT AUTO_INCREMENT PRIMARY KEY,\n  suspect_id INT,\n  action_summary VARCHAR(150) NOT NULL,\n  timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (suspect_id) REFERENCES suspects(suspect_id) ON DELETE CASCADE\n)', 300, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS audit_log;\nDROP TABLE IF EXISTS suspects;\nCREATE TABLE suspects (suspect_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, age INT, status VARCHAR(50) DEFAULT \'Under Investigation\')', 'SHOW COLUMNS FROM audit_log', 1),
(60088, 'Operation Blackout — Master Investigation Schema Finalization', 'Construct the comprehensive `incident_dossier` table uniting officer reports, primary suspect links, and crime scene location:\n- dossier_id (INT, PK, AI)\n- case_title (VARCHAR 150, NOT NULL)\n- location_id (INT, NOT NULL, FK → locations)\n- officer_id (INT, NOT NULL, FK → officers)\n- findings (TEXT)', '📋 OBJECTIVES:\n1. Deploy incident_dossier table. (30 XP)\n2. Establish foreign keys to locations and officers. (35 XP)\n3. Include findings column of type TEXT. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 3, 'CREATE TABLE incident_dossier (\n  dossier_id INT AUTO_INCREMENT PRIMARY KEY,\n  case_title VARCHAR(150) NOT NULL,\n  location_id INT NOT NULL,\n  officer_id INT NOT NULL,\n  findings TEXT,\n  FOREIGN KEY (location_id) REFERENCES locations(location_id),\n  FOREIGN KEY (officer_id) REFERENCES officers(officer_id)\n)', 300, 1, 0, NULL, 'Rank', 'DDL', 'DROP TABLE IF EXISTS incident_dossier;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (location_id INT AUTO_INCREMENT PRIMARY KEY, place_name VARCHAR(100) NOT NULL, district VARCHAR(100), is_active TINYINT(1) DEFAULT 1);\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50))', 'SHOW COLUMNS FROM incident_dossier', 1),
(60089, 'Blackout Intel — Register Infiltrator James Okon', 'An intruder was detained attempting to access municipal power grids. Insert into `suspects`:\n- name: \"James Okon\"\n- age: 35\n- status: \"Under Investigation\"', '📋 OBJECTIVES:\n1. Use INSERT INTO suspects. (30 XP)\n2. Provide name \'James Okon\' and age 35. (35 XP)\n3. Set status to \'Under Investigation\'. (35 XP)\n\n💡 Check your SQL syntax and make sure all required fields are included.', 1, 1, 'INSERT INTO suspects (name, age, status) VALUES (\'James Okon\', 35, \'Under Investigation\')', 100, 1, 0, NULL, 'Rank', 'DML', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (location_id INT AUTO_INCREMENT PRIMARY KEY, place_name VARCHAR(100) NOT NULL, district VARCHAR(100), is_active TINYINT(1) DEFAULT 1);\nCREATE TABLE officers (officer_id INT AUTO_INCREMENT PRIMARY KEY, badge_number VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, rank_level VARCHAR(50));\nCREATE TABLE suspects (suspect_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, age INT, status VARCHAR(50) DEFAULT \'Under Investigation\');\nCREATE TABLE witnesses (witness_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, contact_number VARCHAR(20));\nCREATE TABLE evidence (evidence_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100) NOT NULL, severity INT DEFAULT 1, location_id INT, collected_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (location_id) REFERENCES locations(location_id) ON DELETE SET NULL);\nINSERT INTO locations VALUES (1,\'City Hall\',\'Downtown\',1),(2,\'Central Warehouse\',\'Industrial Zone\',1),(3,\'Riverside Park\',\'Northside\',1),(4,\'Police HQ\',\'Central\',1),(5,\'Abandoned Factory\',\'Southside\',0);\nINSERT INTO officers VALUES (1,\'B-001\',\'Officer Santos\',\'Detective\'),(2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),(3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES (1,\'Marcus Webb\',32,\'Under Investigation\'),(2,\'Lena Torres\',28,\'Under Investigation\'),(3,\'Victor Hale\',45,\'Cleared\'),(4,\'Diana Cruz\',39,\'Arrested\'),(5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES (1,\'Carmen Sia\',\'09171234567\'),(2,\'Roberto Ngo\',\'09281234567\'),(3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),(2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),(3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),(4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),(5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\')', 'SELECT suspect_id, name, age, status FROM suspects ORDER BY suspect_id', 2),
