INSERT INTO `datasets` (`dataset_id`, `dataset_name`, `schema_definition`, `sample_data`) VALUES 
(1, 'Crime Investigation Universe', 'DROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS witnesses;\nDROP TABLE IF EXISTS suspects;\nDROP TABLE IF EXISTS officers;\nDROP TABLE IF EXISTS locations;\nCREATE TABLE locations (\n    location_id INT AUTO_INCREMENT PRIMARY KEY,\n    place_name VARCHAR(100) NOT NULL,\n    district VARCHAR(100),\n    is_active TINYINT(1) DEFAULT 1\n  );\nCREATE TABLE officers (\n    officer_id INT AUTO_INCREMENT PRIMARY KEY,\n    badge_number VARCHAR(20) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    rank_level VARCHAR(50)\n  );\nCREATE TABLE suspects (\n    suspect_id INT AUTO_INCREMENT PRIMARY KEY,\n    name VARCHAR(100) NOT NULL,\n    age INT,\n    status VARCHAR(50) DEFAULT \'Under Investigation\'\n  );\nCREATE TABLE witnesses (\n    witness_id INT AUTO_INCREMENT PRIMARY KEY,\n    full_name VARCHAR(100) NOT NULL,\n    contact_number VARCHAR(20)\n  );\nCREATE TABLE evidence (\n    evidence_id INT AUTO_INCREMENT PRIMARY KEY,\n    item_name VARCHAR(100) NOT NULL,\n    severity INT DEFAULT 1,\n    location_id INT,\n    collected_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (location_id) REFERENCES locations(location_id)\n  );', 'INSERT INTO locations VALUES \n    (1,\'City Hall\',\'Downtown\',1),\n    (2,\'Central Warehouse\',\'Industrial Zone\',1),\n    (3,\'Riverside Park\',\'Northside\',1),\n    (4,\'Police HQ\',\'Central\',1),\n    (5,\'Abandoned Factory\',\'Southside\',0),\n    (6,\'Harbor Pier\',\'Waterfront\',1);\nINSERT INTO officers VALUES \n    (1,\'B-001\',\'Officer Santos\',\'Detective\'),\n    (2,\'B-002\',\'Officer Reyes\',\'Sergeant\'),\n    (3,\'B-003\',\'Officer Lim\',\'Junior Officer\');\nINSERT INTO suspects VALUES \n    (1,\'Marcus Webb\',32,\'Under Investigation\'),\n    (2,\'Lena Torres\',28,\'Under Investigation\'),\n    (3,\'Victor Hale\',45,\'Cleared\'),\n    (4,\'Diana Cruz\',39,\'Arrested\'),\n    (5,\'Ethan Ford\',23,\'Under Investigation\');\nINSERT INTO witnesses VALUES \n    (1,\'Carmen Sia\',\'09171234567\'),\n    (2,\'Roberto Ngo\',\'09281234567\'),\n    (3,\'Felicia Park\',\'09391234567\');\nINSERT INTO evidence VALUES \n    (1,\'Broken Knife\',4,2,\'2026-09-01 10:00:00\'),\n    (2,\'Surveillance Tape\',3,4,\'2026-09-02 14:00:00\'),\n    (3,\'Bloody Glove\',5,1,\'2026-09-03 08:30:00\'),\n    (4,\'Receipt Paper\',1,3,\'2026-09-04 12:00:00\'),\n    (5,\'Crowbar\',3,5,\'2026-09-05 09:15:00\'),\n    (6,\'Security Footprint\',4,2,\'2026-09-06 11:00:00\');'),
(2, 'School Laptop - Suspects Only', '\n\nCREATE TABLE persons (\n    person_id INT PRIMARY KEY,\n    name VARCHAR(100),\n    role VARCHAR(50),\n    age INT,\n    criminal_record TINYINT(1)\n);\n\nCREATE TABLE places (\n    place_id INT PRIMARY KEY,\n    place_name VARCHAR(100),\n    location_type VARCHAR(50)\n);\n\nCREATE TABLE crime_events (\n    crime_id INT PRIMARY KEY AUTO_INCREMENT,\n    crime_name VARCHAR(100),\n    place_id INT,\n    crime_time DATETIME\n);\n\nCREATE TABLE evidence (\n    evidence_id INT PRIMARY KEY,\n    evidence_type VARCHAR(100),\n    person_id INT,\n    place_id INT,\n    severity INT\n);\n\nCREATE TABLE person_locations (\n    record_id INT PRIMARY KEY,\n    person_id INT,\n    place_id INT,\n    visit_time DATETIME\n);\n', '\n\nINSERT INTO persons (person_id, name, role, age, criminal_record) VALUES\n(1, \'Alex Carter\', \'Student\', 19, 0),\n(2, \'Bianca Reyes\', \'Student\', 21, 0),\n(3, \'Carlos Mendoza\', \'Guard\', 34, 1),\n(4, \'Diana Lopez\', \'Teacher\', 29, 0),\n(5, \'Ethan Cruz\', \'Student\', 22, 1);\n\nINSERT INTO places (place_id, place_name, location_type) VALUES\n(1, \'Library\', \'Academic\'),\n(3, \'Laboratory\', \'Restricted\'),\n(5, \'Warehouse\', \'Restricted\');\n\n'),
(3, 'School Laptop - Evidence Investigation', '\n\nCREATE TABLE persons (\n    person_id INT PRIMARY KEY,\n    name VARCHAR(100),\n    role VARCHAR(50),\n    age INT,\n    criminal_record TINYINT(1)\n);\n\nCREATE TABLE places (\n    place_id INT PRIMARY KEY,\n    place_name VARCHAR(100),\n    location_type VARCHAR(50)\n);\n\nCREATE TABLE crime_events (\n    crime_id INT PRIMARY KEY AUTO_INCREMENT,\n    crime_name VARCHAR(100),\n    place_id INT,\n    crime_time DATETIME\n);\n\nCREATE TABLE evidence (\n    evidence_id INT PRIMARY KEY,\n    evidence_type VARCHAR(100),\n    person_id INT,\n    place_id INT,\n    severity INT\n);\n\nCREATE TABLE person_locations (\n    record_id INT PRIMARY KEY,\n    person_id INT,\n    place_id INT,\n    visit_time DATETIME\n);\n', '\nINSERT INTO crime_events (crime_id, crime_name, place_id, crime_time) VALUES\n(1, \'Warehouse Break-in\', 5, \'2026-04-10 10:30:00\'),\n(2, \'Lab Equipment Theft\', 3, \'2026-04-10 10:45:00\'),\n(3, \'Library Data Leak\', 1, \'2026-04-09 15:00:00\');\n\nINSERT INTO persons (person_id, name, role, age, criminal_record) VALUES\n(1, \'Alex Carter\', \'Student\', 19, 0),\n(2, \'Bianca Reyes\', \'Student\', 21, 0),\n(3, \'Carlos Mendoza\', \'Guard\', 34, 1),\n(4, \'Diana Lopez\', \'Teacher\', 29, 0),\n(5, \'Ethan Cruz\', \'Student\', 22, 1),\n(6, \'Fiona Garcia\', \'Nurse\', 31, 0),\n(7, \'George Ramos\', \'Janitor\', 45, 1),\n(8, \'Hannah Lee\', \'Student\', 18, 0),\n(9, \'Ivan Torres\', \'Technician\', 28, 0),\n(10, \'Julia Santos\', \'Teacher\', 41, 0),\n(11, \'Kevin Lim\', \'Student\', 23, 0),\n(12, \'Lara Flores\', \'Student\', 20, 1),\n(13, \'Mark Dela Cruz\', \'Guard\', 38, 0),\n(14, \'Nina Ortiz\', \'Student\', 19, 0),\n(15, \'Oscar Villanueva\', \'Staff\', 33, 1);\n\nINSERT INTO places (place_id, place_name, location_type) VALUES\n(1, \'Library\', \'Academic\'),\n(2, \'Cafeteria\', \'Public\'),\n(3, \'Laboratory\', \'Restricted\'),\n(4, \'Main Office\', \'Administrative\'),\n(5, \'Warehouse\', \'Restricted\'),\n(6, \'Clinic\', \'Medical\');\n\nINSERT INTO evidence (evidence_id, evidence_type, person_id, place_id, severity) VALUES\n(1, \'Fingerprint\', 3, 5, 3),\n(2, \'Broken Lock\', 5, 3, 4),\n(3, \'Security Footage\', 7, 5, 5),\n(4, \'Suspicious Email\', 12, 1, 2),\n(5, \'Access Card Log\', 15, 5, 4),\n(6, \'Tool Found\', 7, 5, 3),\n(7, \'Witness Report\', 3, 5, 2),\n(8, \'USB Device\', 5, 3, 5);\n\nINSERT INTO person_locations (record_id, person_id, place_id, visit_time) VALUES\n(1, 3, 5, \'2026-04-10 10:15:00\'),\n(2, 5, 3, \'2026-04-10 10:30:00\'),\n(3, 7, 5, \'2026-04-10 09:50:00\'),\n(4, 12, 1, \'2026-04-09 14:00:00\'),\n(5, 2, 2, \'2026-04-09 12:15:00\'),\n(6, 11, 3, \'2026-04-10 11:00:00\'),\n(7, 1, 1, \'2026-04-08 08:00:00\'),\n(8, 15, 5, \'2026-04-10 10:40:00\'),\n(9, 9, 3, \'2026-04-10 09:00:00\'),\n(10, 4, 4, \'2026-04-10 13:00:00\');\n');
